        ? "failed"
        : snap.evidence?.structured.status === "saved"
          ? "saved"
          : "unknown",
    effectiveCwd: snap.cwd,
    requestedCwd: snap.requestedCwd,
    isolation: snap.worktreeBranch ? "worktree" : "shared",
    branch: snap.worktreeBranch,
    baseSha: snap.worktreeBaseSha,
  });
